mapper.select:
SELECT COUNT(*)
FROM tracking.inquiry_record
WHERE channel = 'WEB_SELF'
  AND inquirer_user_id = #{userId}
  AND tracking_number = #{trackingNumber}
  AND received_at > #{after}

SELECT id, channel, shipper_company_id, tracking_number, inquirer_kind, inquirer_user_id, received_at,
       escalated, case_number, recorded_by, created_at
FROM tracking.inquiry_record
WHERE channel = 'WEB_SELF'
  AND escalated = FALSE
  AND shipper_company_id = #{shipperCompanyId}
  AND tracking_number = #{trackingNumber}
  AND received_at >= #{from}
  AND received_at <= #{to}
ORDER BY received_at

SELECT COUNT(*)
FROM tracking.inquiry_record
WHERE received_at >= #{from} AND received_at < #{to}

mapper.update:
UPDATE tracking.inquiry_record
   SET escalated = TRUE, case_number = #{caseNumber}
 WHERE id = #{id} AND escalated = FALSE
